-- Fireside (Mile High Spirits, Denver; maker site drinkmhs.com) importer, applied 2026-10-12 via catalog/sources/bourbon/fireside.py.
-- The brand has no site of its own (firesidewhiskey.com does not resolve; milehighspirits.com is a parked, robots-disallowed
-- placeholder). drinkmhs.com is a JS single-page app whose whole catalogue is an array in /assets/index-<hash>.js.
-- 3 corrections (maker page/image recorded), 5 confirmations, 5 additions (Fireside Bourbon 80, Barrel Share 88, Cabernet Finish 105.6,
-- Hazmat Proof 143.5/8yr, Strato 106), 1 merge. Nothing marked discontinued: the 9 seed rows the maker's page does not list were never
-- on it (rye / Triple Rye / per-barrel picks), so "gone from the site" is not evidence; see the report.
-- MERGE: seed "Fireside Single Barrel (8 Years)" (73dedb34..., 143.5 proof, 8 yr) -> the new "Fireside Hazmat Proof" row. The maker's
-- Hazmat page says "The current release is 8 years old at 143.5 proof", i.e. the same bottling. NOT merged (separate barrels/releases,
-- different proof or age): Single Barrel Hazmat Proof 141.2/6yr, Single Barrel (7 Year) 142, (5 Year) 122, Wheated Single Barrel 133.1,
-- Single Barrel 4yr 105.6, the three Single Barrel Rye / Triple Rye rows, 8 Year (105.6 small batch, a different product from Hazmat).
update cellar.makers set website = coalesce(website, 'https://drinkmhs.com'), country = coalesce(country, 'US') where id = '36a4c66e-f573-47c6-b4ad-e5bb8080cc11';
update cellar.products set specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://drinkmhs.com/assets/fireside-bottled-in-bond-CIxR9tEg.png'), producer = coalesce(producer, 'Mile High Spirits'), producer_id = coalesce(producer_id, '36a4c66e-f573-47c6-b4ad-e5bb8080cc11'::uuid), source = 'maker', source_url = 'https://drinkmhs.com/spirits/fireside-bottled-in-bond', source_checked_at = now(), discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'shelf'::cellar.rarity) where id = 'd97d25c4-7f2c-4714-8880-eba1fba86e3d' and facts_verified_at is null;
update cellar.products set specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://drinkmhs.com/assets/wheated-bottled-in-bond-r3_B8Hd5.png'), producer = coalesce(producer, 'Mile High Spirits'), producer_id = coalesce(producer_id, '36a4c66e-f573-47c6-b4ad-e5bb8080cc11'::uuid), source = 'maker', source_url = 'https://drinkmhs.com/spirits/wheated-bottled-in-bond', source_checked_at = now(), discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'shelf'::cellar.rarity) where id = '8ab9afeb-5fac-4f67-a1f7-51e20ef75964' and facts_verified_at is null;
update cellar.products set specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://drinkmhs.com/assets/fireside-port-finish-BDWA4hsk.png'), producer = coalesce(producer, 'Mile High Spirits'), producer_id = coalesce(producer_id, '36a4c66e-f573-47c6-b4ad-e5bb8080cc11'::uuid), source = 'maker', source_url = 'https://drinkmhs.com/spirits/fireside-port-finish', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'limited'::cellar.rarity) where id = '0cc45bf2-d2f8-4071-afaf-058a7988d10c' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('065e4e79-c68e-4f5a-bcf5-d04c07d672cb', '9ea4b414-e195-4bb3-b3ea-077e5f6ad921', '0ed30c99-af8b-4e2f-8141-743a7108a51e', '3814a016-4562-4344-9a29-87ac07195425', '54a0a514-320f-4eda-882f-6d494fdc8c9b', 'd97d25c4-7f2c-4714-8880-eba1fba86e3d', '8ab9afeb-5fac-4f67-a1f7-51e20ef75964', '0cc45bf2-d2f8-4071-afaf-058a7988d10c');
update cellar.products set source = 'maker', source_url = 'https://drinkmhs.com/spirits/fireside-8-year', discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'allocated'::cellar.rarity), producer = coalesce(producer, 'Mile High Spirits'), producer_id = coalesce(producer_id, '36a4c66e-f573-47c6-b4ad-e5bb8080cc11'::uuid) where id = '065e4e79-c68e-4f5a-bcf5-d04c07d672cb' and facts_verified_at is null;
update cellar.products set source = 'maker', source_url = 'https://drinkmhs.com/spirits/fireside-pinot-finish', discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'limited'::cellar.rarity), producer = coalesce(producer, 'Mile High Spirits'), producer_id = coalesce(producer_id, '36a4c66e-f573-47c6-b4ad-e5bb8080cc11'::uuid) where id = '9ea4b414-e195-4bb3-b3ea-077e5f6ad921' and facts_verified_at is null;
update cellar.products set source = 'maker', source_url = 'https://drinkmhs.com/spirits/fireside-rye-barrel-finish', discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'limited'::cellar.rarity), producer = coalesce(producer, 'Mile High Spirits'), producer_id = coalesce(producer_id, '36a4c66e-f573-47c6-b4ad-e5bb8080cc11'::uuid) where id = '0ed30c99-af8b-4e2f-8141-743a7108a51e' and facts_verified_at is null;
update cellar.products set source = 'maker', source_url = 'https://drinkmhs.com/spirits/fireside-straight-malt', discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'limited'::cellar.rarity), producer = coalesce(producer, 'Mile High Spirits'), producer_id = coalesce(producer_id, '36a4c66e-f573-47c6-b4ad-e5bb8080cc11'::uuid) where id = '3814a016-4562-4344-9a29-87ac07195425' and facts_verified_at is null;
update cellar.products set source = 'maker', source_url = 'https://drinkmhs.com/spirits/fireside-peated-single-malt', discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'shelf'::cellar.rarity), producer = coalesce(producer, 'Mile High Spirits'), producer_id = coalesce(producer_id, '36a4c66e-f573-47c6-b4ad-e5bb8080cc11'::uuid) where id = '54a0a514-320f-4eda-882f-6d494fdc8c9b' and facts_verified_at is null;
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Fireside Bourbon","rar":"shelf","f":"Fireside","x":null,"p":80.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["Fireside"],"img":null,"u":"https://drinkmhs.com/spirits/fireside-bourbon","pr":"Mile High Spirits","mk":"36a4c66e-f573-47c6-b4ad-e5bb8080cc11"},{"n":"Fireside Cabernet Finish","rar":"limited","f":"Fireside","x":"Cabernet Finish","p":105.6,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":"Cabernet Sauvignon Wine Casks","msrp":null,"core":false,"al2":[],"img":null,"u":"https://drinkmhs.com/spirits/fireside-cabernet-finish","pr":"Mile High Spirits","mk":"36a4c66e-f573-47c6-b4ad-e5bb8080cc11"},{"n":"Fireside Barrel Share","rar":"limited","f":"Fireside","x":"Barrel Share","p":88.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://drinkmhs.com/assets/fireside-barrel-share-BSjCL-uT.png","u":"https://drinkmhs.com/spirits/fireside-barrel-share","pr":"Mile High Spirits","mk":"36a4c66e-f573-47c6-b4ad-e5bb8080cc11"},{"n":"Fireside Hazmat Proof","rar":"allocated","f":"Fireside","x":"Hazmat Proof","p":143.5,"ay":8.0,"al":"8 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":true,"fin":null,"msrp":null,"core":false,"al2":[],"img":null,"u":"https://drinkmhs.com/spirits/fireside-hazmat","pr":"Mile High Spirits","mk":"36a4c66e-f573-47c6-b4ad-e5bb8080cc11"},{"n":"Fireside Strato Whiskey","rar":"limited","f":"Fireside","x":"Strato Whiskey","p":106.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"high_rye","mb":"70% Corn, 20% Rye, 10% Malted Barley","st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":null,"u":"https://drinkmhs.com/spirits/strato-whiskey","pr":"Mile High Spirits","mk":"36a4c66e-f573-47c6-b4ad-e5bb8080cc11"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
select cellar.merge_product('73dedb34-3058-4b60-bbe3-ae2bb2ad6031'::uuid, (select id from cellar.products where type = 'bourbon' and brand_family = 'Fireside' and expression = 'Hazmat Proof' and merged_into is null), null); -- Single Barrel (8 Years) 143.5 -> Hazmat Proof (current release 8 yr 143.5)
